function validate([isConnected]) {
  const n = Array.isArray(isConnected) ? isConnected.length : 0;
  if (n < 1 || n > 200) return 'isConnected needs 1 to 200 rows.';
  if (isConnected.some(row => !Array.isArray(row) || row.length !== n)) return 'isConnected must be square: every row has n values.';
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const value = isConnected[i][j];
      if (value !== 0 && value !== 1) return 'Every entry is 0 or 1.';
      if (value !== isConnected[j][i]) return 'isConnected must be symmetric.';
    }
    if (isConnected[i][i] !== 1) return 'Every city is connected to itself: isConnected[i][i] is 1.';
  }
  return null;
}

