function findCircleNum(isConnected) {
  const n = isConnected.length;
  const visited = new Array(n).fill(false);
  let provinces = 0;

  const dfs = (city) => {
    visited[city] = true;
    for (let other = 0; other < n; other++) {
      if (isConnected[city][other] === 1 && !visited[other]) {
        dfs(other);
      }
    }
  };

  for (let city = 0; city < n; city++) {
    if (!visited[city]) {
      provinces++;
      dfs(city);
    }
  }
  return provinces;
}

