function findCircleNum(isConnected) {
  // Every city starts with its own label; linked cities keep taking the smaller label until nothing changes.
  const n = isConnected.length;
  const label = Array.from({ length: n }, (_, i) => i);
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (isConnected[i][j] === 1 && label[j] < label[i]) { label[i] = label[j]; changed = true; }
  }
  return new Set(label).size;
}

