function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(90, 100) : int(1, 8);
  const grid = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));
  const link = (a, b) => { grid[a][b] = 1; grid[b][a] = 1; };
  if (rand() < 0.5) {
    // Random graph: a low chance of each link gives many provinces, a higher one merges them.
    const chances = [0, 0.5 / n, 1 / n, 1.5 / n, 3 / n, 0.3];
    const chance = chances[int(0, chances.length - 1)];
    for (let i = 0; i < n; i++)
      for (let j = i + 1; j < n; j++)
        if (rand() < chance) link(i, j);
  } else {
    // Shuffled groups, each joined by a chain (so links are often indirect) plus a few extra links.
    const order = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) { const j = int(0, i); [order[i], order[j]] = [order[j], order[i]]; }
    const groups = int(1, Math.max(1, Math.ceil(n / int(1, 6))));
    const owner = order.map(() => int(0, groups - 1));
    for (let g = 0; g < groups; g++) {
      const members = order.filter((_, k) => owner[k] === g);
      for (let k = 1; k < members.length; k++) link(members[k - 1], members[k]);
      for (let extra = 0; extra < members.length; extra++) {
        if (members.length > 1 && rand() < 0.3) link(members[int(0, members.length - 1)], members[int(0, members.length - 1)]);
      }
    }
  }
  return [grid];
}
